<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>City Skyline Day‑Night Cycle</title>
<style>
  body,html{margin:0;padding:0;height:100%;overflow:hidden;background:#000}
  canvas{display:block;width:100%;height:100%}
</style>
</head>
<body>
<canvas id="c"></canvas>
<script>
(() => {
  const canvas = document.getElementById('c');
  const ctx = canvas.getContext('2d');

  // resize canvas
  function resize() {
    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight;
    initBuildings();
  }
  window.addEventListener('resize', resize);
  resize();

  // ---------- SKY ----------
  const dayColor = {r:135,g:206,b:235};   // #87CEEB
  const nightColor = {r:0,g:29,b:61};     // #001d3d

  function lerp(a,b,t){return a+(b-a)*t;}

  function skyColor(factor){ // factor 0=day,1=night
    const r=lerp(dayColor.r,nightColor.r,factor);
    const g=lerp(dayColor.g,nightColor.g,factor);
    const b=lerp(dayColor.b,nightColor.b,factor);
    return `rgb(${r|0},${g|0},${b|0})`;
  }

  // ---------- STARS ----------
  const starCount = 200;
  const stars = [];
  for(let i=0;i<starCount;i++){
    stars.push({
      x:Math.random()*canvas.width,
      y:Math.random()*canvas.height*0.6,
      r:Math.random()*1.5+0.5
    });
  }

  // ---------- BUILDINGS ----------
  const buildings = [];
  function initBuildings(){
    buildings.length=0;
    const baseY = canvas.height*0.6;
    let x=0;
    while(x<canvas.width){
      const w = 50+Math.random()*80;
      const h = 150+Math.random()*200;
      const b = {
        x,
        y: baseY - h,
        w,
        h,
        rows: Math.floor(h/20),
        cols: Math.floor(w/15)
      };
      buildings.push(b);
      x+=w+20;
    }
    // reposition stars after resize
    for(let s of stars){
      s.x = Math.random()*canvas.width;
      s.y = Math.random()*canvas.height*0.6;
    }
  }

  // ---------- ANIMATION ----------
  function draw(timestamp){
    const t = (timestamp/1000)%10;            // 0‑10 sec loop
    const phase = t/10;                       // 0‑1
    const angle = phase*2*Math.PI;
    const dayFactor = (Math.cos(angle)+1)/2; // 1 at noon, 0 at midnight
    const nightFactor = 1 - dayFactor;

    // SKY
    ctx.fillStyle = skyColor(nightFactor);
    ctx.fillRect(0,0,canvas.width,canvas.height);

    // STARS (fade in/out)
    ctx.fillStyle = `rgba(255,255,255,${nightFactor*0.8})`;
    for(let s of stars){
      ctx.beginPath();
      ctx.arc(s.x,s.y,s.r,0,2*Math.PI);
      ctx.fill();
    }

    // SUN / MOON
    const horizon = canvas.height*0.6;
    const radius = canvas.width*0.4;
    const cx = canvas.width/2;
    const cy = horizon;
    const sunX = cx + radius*Math.cos(angle);
    const sunY = cy - radius*Math.sin(angle);
    if(dayFactor>0.5){
      // SUN
      ctx.fillStyle = '#ffdd55';
      ctx.beginPath();
      ctx.arc(sunX,sunY,40,0,2*Math.PI);
      ctx.fill();
    }else{
      // MOON
      ctx.fillStyle = '#f0e6d2';
      ctx.beginPath();
      ctx.arc(sunX,sunY,30,0,2*Math.PI);
      ctx.fill();
      // crescent effect
      ctx.fillStyle = skyColor(nightFactor);
      ctx.beginPath();
      ctx.arc(sunX+12,sunY-5,30,0,2*Math.PI);
      ctx.fill();
    }

    // BUILDINGS
    for(let b of buildings){
      ctx.fillStyle = '#222';
      ctx.fillRect(b.x,b.y,b.w,b.h);
      // windows
      const winW = b.w/ b.cols *0.6;
      const winH = b.h/ b.rows *0.6;
      const offsetX = (b.w - b.cols*winW)/2;
      const offsetY = (b.h - b.rows*winH)/2;
      for(let r=0;r<b.rows;r++){
        for(let c=0;c<b.cols;c++){
          const wx = b.x + offsetX + c*winW*1.3;
          const wy = b.y + offsetY + r*winH*1.3;
          if(nightFactor>0.3 && Math.random()<0.3){ // lit window
            ctx.fillStyle = `rgba(255,215,0,${0.6+0.4*nightFactor})`;
          }else{
            ctx.fillStyle = `rgba(0,0,0,${0.8})`;
          }
          ctx.fillRect(wx,wy,winW,winH);
        }
      }
    }

    requestAnimationFrame(draw);
  }
  requestAnimationFrame(draw);
})();
</script>
</body>
</html>
```

The script continuously computes the time‑of‑day factor, interpolates the sky colour, moves a sun/moon along an arc, fades stars, and randomly lights building windows during the night to create a 10‑second looping day‑night animation.
